#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "durbin.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_1D(r,N,n))
{
  int i, j;

  for (i = 0; i < n; i++)
    {
      r[i] = (n+1-i);
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/*
 * Main computational kernel. The whole function will be timed,
 * including the call and return.
 *
 * Optimizations compared to the original PolyBench version:
 *  - Create a single reversed copy of r[] once (O(n)) so that the
 *    inner dot-product over k has unit-stride accesses in both
 *    operands, improving cache locality and helping auto-vectorization.
 *  - Replace the temporary z[] array and the subsequent copy-back by
 *    an in-place, symmetric update of y[]. Each (i, j) pair with
 *    j = k-1-i is updated using the original values, preserving the
 *    exact numerical semantics while halving memory traffic.
 *  - Use local restrict-qualified pointer aliases for r and y to
 *    make non-aliasing explicit to the compiler.
 */
static
void kernel_durbin[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  /* Local restrict aliases for better optimization and vectorization.
   * After these are introduced, the original r and y identifiers are
   * no longer used, so the restrict-contract is respected.
   */
  DATA_TYPE * restrict const r_ = r;
  DATA_TYPE * restrict const y_ = y;

  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

  int i, k;

  /* Reversed copy of r:
   *   r_rev[idx] = r[n-1-idx]
   * This allows us to rewrite r[k-1-i] as r_rev[n-k+i], so that
   * the inner dot-product loop accesses both r_rev and y_ with
   * contiguous, increasing indices.
   *
   * This is O(n) work done once, and is negligible compared to the
   * O(n^2) cost of the Durbin recursion itself.
   */
  DATA_TYPE r_rev[N];
  for (i = 0; i < n; i++) {
    r_rev[i] = r_[n - 1 - i];
  }

#pragma scop
  y_[0] = -r_[0];
  beta = SCALAR_VAL(1.0);
  alpha = -r_[0];

  for (k = 1; k < _PB_N; k++) {
    beta = (1 - alpha*alpha) * beta;
    sum = SCALAR_VAL(0.0);

    /* Original expression:
     *   sum += r[k-1-i] * y[i],   i = 0..k-1
     *
     * With r_rev[idx] = r[n-1-idx], we have:
     *   r[k-1-i] = r_rev[n-1-(k-1-i)] = r_rev[n-k+i]
     *
     * Define offset = n-k; then:
     *   r[k-1-i] == r_rev[offset + i]
     * so both r_rev[offset + i] and y_[i] are unit-stride.
     */
    int offset = n - k;
    for (i = 0; i < k; i++) {
      sum += r_rev[offset + i] * y_[i];
    }

    alpha = -(r_[k] + sum) / beta;

    /* In-place symmetric update of y_[0..k-1] without a temporary z[].
     *
     * Original code:
     *   for (i = 0; i < k; i++)
     *     z[i] = y[i] + alpha * y[k-i-1];
     *   for (i = 0; i < k; i++)
     *     y[i] = z[i];
     *
     * This defines:
     *   new_y[i] = old_y[i] + alpha * old_y[k-1-i]
     *
     * We can update pairs (i, j) with j = k-1-i using their original
     * values (yi, yj) as:
     *   new_y[i] = yi + alpha * yj
     *   new_y[j] = yj + alpha * yi
     *
     * For odd k, there is a middle index mid = (k-1)/2 where i == j:
     *   new_y[mid] = old_y[mid] + alpha * old_y[mid]
     *              = (1 + alpha) * old_y[mid]
     *
     * This reproduces exactly the original transformation of y.
     */
    int half = k >> 1; /* floor(k/2) */

    for (i = 0; i < half; i++) {
      int j = k - 1 - i;
      DATA_TYPE yi = y_[i];
      DATA_TYPE yj = y_[j];
      y_[i] = yi + alpha * yj;
      y_[j] = yj + alpha * yi;
    }

    /* Handle the middle element when k is odd (i == j). */
    if (k & 1) {
      int mid = half; /* since k = 2*half + 1 */
      DATA_TYPE ym = y_[mid];
      y_[mid] = ym + alpha * ym;
    }

    y_[k] = alpha;
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(r, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(r));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_durbin (n,
		 POLYBENCH_ARRAY(r),
		 POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(r);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
