 *   mathematical result while halving the number of array traversals
 *   and improving cache locality.
 * - Use pointer arithmetic in the inner summation loop to simplify
 *   index calculations and help the compiler generate tight code.
 */
static
void kernel_durbin[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_1D(r,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  DATA_TYPE alpha;
  DATA_TYPE beta;
  DATA_TYPE sum;

  int k;

#pragma scop
  y[0] = -r[0];
  beta = SCALAR_VAL(1.0);
  alpha = -r[0];

  for (k = 1; k < _PB_N; k++) {
    beta = (SCALAR_VAL(1.0) - alpha*alpha) * beta;
    sum = SCALAR_VAL(0.0);

    /* Compute: sum = \sum_{i=0}^{k-1} r[k-i-1] * y[i]
       using pointer arithmetic for better locality and simpler
       index expressions. */
    {
      const DATA_TYPE *r_ptr = r + k - 1; /* starts at r[k-1], moves backward */
      const DATA_TYPE *y_ptr = y;         /* starts at y[0], moves forward  */
      int i;

      for (i = 0; i < k; ++i) {
        sum += (*r_ptr--) * (*y_ptr++);
      }
    }

    alpha = - (r[k] + sum) / beta;

    /* In-place symmetric update of y[0..k-1].
       Original code:
         for (i=0; i<k; i++)
           z[i] = y[i] + alpha * y[k-i-1];
         for (i=0; i<k; i++)
           y[i] = z[i];
