       simultaneously, using the old values of y[i] and y[j]:

         y'[i] = y[i] + alpha * y[j]
         y'[j] = y[j] + alpha * y[i]

       This is mathematically identical and preserves numerical
       semantics per element (multiply then add), while reducing
       memory traffic and improving data locality. */
    {
      int i = 0;
      int j = k - 1;

      /* Process pairs (i, j) with i < j. */
      for (; i < j; ++i, --j) {
        DATA_TYPE yi = y[i];
        DATA_TYPE yj = y[j];
        y[i] = yi + alpha * yj;
        y[j] = yj + alpha * yi;
      }

      /* If k is odd, there is one middle element left (i == j),
         which must be updated once using its original value. */
      if (i == j) {
        DATA_TYPE y_mid = y[i];
        y[i] = y_mid + alpha * y_mid;
      }
    }

    y[k] = alpha;
  }
#pragma endscop

